// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up two users with different addresses
        address alice = address(0x1);
        address bob = address(0x2);

        // Deposit 1 ETH each
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        c.deposit{value: 1 ether}();

        vm.deal(bob, 1 ether);
        vm.prank(bob);
        c.deposit{value: 1 ether}();

        // Alice withdraws all - reference succeeds, bug version reverts
        vm.prank(alice);
        // Use try/catch to catch revert
        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: require(callResult) passes => ok == true
        // Bug:     require(!callResult) fails => ok == false
        assertTrue(ok);
    }
}

